<script>
const endpoint=@json(route('dashboard.data',['region'=>$region]));
const statusText={available:'Verfügbar',busy:'Im Einsatz',unavailable:'Nicht verfügbar',disconnected:'Keine Verbindung'};
function safeText(value){return document.createTextNode(value??'—')}
function render(data){const c=data.counts; for(const k of ['total','available','busy']) document.getElementById(k).textContent=c[k];document.getElementById('notavailable').textContent=c.disconnected+c.unavailable;
 const tbody=document.getElementById('providers');tbody.replaceChildren(); if(!data.providers.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=4;td.textContent='Noch keine Dienstleister eingetragen.';tr.append(td);tbody.append(tr);}
 for(const p of data.providers){const tr=document.createElement('tr');const name=document.createElement('td'),strong=document.createElement('strong'),city=document.createElement('span');strong.append(safeText(p.name));city.className='muted';city.append(safeText(p.city));name.append(strong,document.createElement('br'),city);const status=document.createElement('td'),badge=document.createElement('span');badge.className='badge '+p.status;badge.textContent=statusText[p.status]??p.status;status.append(badge);const phone=document.createElement('td'),seen=document.createElement('td');phone.append(safeText(p.phone));seen.append(safeText(p.last_seen));tr.append(name,status,phone,seen);tbody.append(tr)}document.getElementById('updated').textContent='· Stand '+new Date().toLocaleTimeString('de-DE');}
async function refresh(){try{const response=await fetch(endpoint,{cache:'no-store',credentials:'same-origin'});if(!response.ok)throw Error();render(await response.json())}catch{document.getElementById('updated').textContent='· Aktualisierung fehlgeschlagen'}}
setInterval(refresh,15000);
</script>
